styles:
::-webkit-scrollbar { display: none; }
body {
    font-family: 'Inter', sans-serif;
    background-color: #0B0D17;
    color: #F8FAFC;
    scroll-behavior: smooth;
}
.hero-glow {
    background: radial-gradient(circle at 50% 0%, rgba(212, 175, 55, 0.15), transparent 70%);
}
.glass-card {
    background: rgba(21, 24, 40, 0.6);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.08);
}
.gold-glow {
    box-shadow: 0 0 20px rgba(212, 175, 55, 0.2);
}
.blob-bg {
    background: radial-gradient(circle, rgba(212, 175, 55, 0.15) 0%, rgba(11, 13, 23, 0) 70%);
}
.nav-dropdown {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    margin-top: 0.5rem;
    min-width: 200px;
    background: rgba(21, 24, 40, 0.95);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 12px;
    padding: 0.5rem;
    z-index: 100;
}
.nav-item:hover .nav-dropdown {
    display: block;
}
.submenu-nav {
    position: sticky;
    top: 72px;
    z-index: 40;
    background: rgba(11, 13, 23, 0.95);
    backdrop-filter: blur(12px);
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}
.submenu-nav a.active {
    color: #D4AF37;
    border-bottom: 2px solid #D4AF37;
}

twConfigs:
tailwind.config = {
            theme: {
                extend: {
                    fontFamily: {
                        sans: ['Inter', 'sans-serif'],
                    },
                    colors: {
                        bg: {
                            main: '#0B0D17',
                            secondary: '#151828',
                            elevated: '#1F243B',
                            muted: '#2D3554'
                        },
                        gold: {
                            DEFAULT: '#D4AF37',
                            light: '#C5A028',
                            glow: 'rgba(212, 175, 55, 0.4)'
                        },
                        text: {
                            primary: '#F8FAFC',
                            secondary: '#94A3B8',
                            dim: '#64748B'
                        }
                    }
                }
            }
        }

scripts:
document.addEventListener('DOMContentLoaded', function() {
    const submenuLinks = document.querySelectorAll('.submenu-nav a');

    submenuLinks.forEach(link => {
        link.addEventListener('click', function(e) {
            submenuLinks.forEach(l => l.classList.remove('active'));
            this.classList.add('active');
        });
    });

    const sections = document.querySelectorAll('section[id]');
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                const id = entry.target.getAttribute('id');
                submenuLinks.forEach(link => {
                    link.classList.remove('active');
                    if (link.getAttribute('href') === `#${id}`) {
                        link.classList.add('active');
                    }
                });
            }
        });
    }, { threshold: 0.3 });

    sections.forEach(section => observer.observe(section));
});
